  card.innerHTML=`<canvas width="280" height="120" aria-hidden="true"></canvas><span class="skin-weapon">${String(level.tier+1).padStart(2,'0')} · ${level.weapon}</span><strong>${level.name}</strong><span class="skin-action"></span>`;
