$('skin-filter').addEventListener('change',updateSkins);

function renderChain() {
  const steps=$('upgrade-chain');steps.replaceChildren();
  const mission=activeMission();
  const bestOnField=Math.max(mission?.dropTier??highest,...world.bodies.filter(b=>!b.mystery).map(b=>b.tier));
  const start=Math.min(bestOnField,mission?mission.target-2:LEVELS.length-3);
  const highlighted=mission?mission.target:highest;
  for(let tier=start;tier<start+3;tier++){
    const level=LEVELS[tier],item=document.createElement('li');
    item.className='chain-step';item.classList.toggle('current',tier===highlighted);
    if(tier===highlighted)item.setAttribute('aria-current','step');
    const stage=mission?(tier===mission.target?'ЦІЛЬ РІВНЯ':'ПОКРАЩЕННЯ'):(tier===highest?'ТВІЙ РІВЕНЬ':tier<highest?'В АРСЕНАЛІ':'НАСТУПНИЙ СКІН');
    item.innerHTML=`<span class="chain-stage">${stage}</span><canvas width="140" height="60" aria-hidden="true"></canvas><strong>${level.weapon}</strong><span>${level.name}</span>`;
    drawWeapon(item.querySelector('canvas').getContext('2d'),level.weaponTier,70,30,125,0,level.variant);
    steps.append(item);
  }
  $('chain-progress').textContent=`${highest+1} / ${LEVELS.length}`;
}

function updateScore() {
  $('score').textContent=String(world.score).padStart(4,'0');$('merges').textContent=world.merges;
  if(world.score>best){best=world.score;$('best').textContent=best.toLocaleString('uk-UA');try{localStorage.setItem(bestKey(),String(best));}catch{}}
}
function merged(e) {
  for(const body of e.retired){
    bursts.push({x:body.x,y:body.y,radius:body.r,color:LEVELS[body.tier].color,age:15});
  }
  if(current<world.minimumTier)current=world.minimumTier;
  if(next<world.minimumTier)next=world.minimumTier;
  const color=LEVELS[Math.min(e.tier,LEVELS.length-1)].color;
  const radius=world.radius(Math.min(e.tier,LEVELS.length-1));
  bursts.push({x:e.x,y:e.y,radius,color,age:0});
  const sparkCount=reducedMotion?8:36;
  for(let i=0;i<sparkCount;i++) {const angle=Math.PI*2*i/sparkCount+Math.random()*.18,speed=2+Math.random()*5;particles.push({x:e.x,y:e.y,vx:Math.cos(angle)*speed,vy:Math.sin(angle)*speed,life:1,color,size:1.5+Math.random()*2.5});}
  floaters.push({x:e.x,y:e.y-radius-12,text:`+${e.points}`,life:1,color});
  // The two halves fly apart when the case opens.
  for(const sign of [-1,1])particles.push({x:e.x,y:e.y,vx:sign*4,vy:-3,life:1,color,size:radius*.8,shard:true,rotation:sign*.2});
  if(e.tier<LEVELS.length)discovered.add(e.tier);
  highest=Math.max(highest,Math.min(e.tier,LEVELS.length-1));hudDirty=true;soundEffect(e.tier,true);
  if(particles.length>240)particles.splice(0,particles.length-240);
  if(bursts.length>32)bursts.splice(0,bursts.length-32);
  if(floaters.length>32)floaters.splice(0,floaters.length-32);
  checkMission(e.tier);
}
function reset(advance = false) {
  advance=advance&&mode==='missions';
  if(!advance){
    secretTier=null;
    resetSecretPosition();
    $('golden-secret').setAttribute('aria-pressed','false');
    clearTimeout(secretNoticeTimer);$('secret-notice').textContent='';
  }
  const score=advance?world.score:0,merges=advance?world.merges:0;
  if(advance)missionIndex++;else{missions=mode==='missions'?createMissions(Math.random,difficulty):[];missionIndex=0;discovered=new Set();}
  const mission=activeMission();missionComplete=false;
  world=new World(520,630,merged,{difficulty,secretTier,...(mission?{mission,onMystery:mysteryChanged,mysteryRewards:mission.mysteryRewards}:{})});
  world.score=score;world.merges=merges;world.seedCases();
  for(const body of world.bodies)if(!body.mystery)discovered.add(body.tier);
  highest=Math.max(...discovered);current=randomTier();next=randomTier();cooldown=0;particles=[];floaters=[];bursts=[];won=false;aim=260;aimSample=null;flick=0;victoryDelay=0;hudDirty=false;accumulator=0;playSeconds=0;
  const mysteryHits=difficultySettings(difficulty).mysteryHits;
  $('mystery-count').textContent=`0 / ${mysteryHits}`;$('mystery-progress').max=mysteryHits;$('mystery-progress').value=0;
  $('mystery-hint').textContent='';
  updateMode();closeModal();updateScore();renderNext();updateArsenal(true);updateMission();
  updateClocks(true);
  drop();
}
function drop() {
  if(paused||document.hidden||world.over||cooldown>0||missionComplete)return;
  const body=world.add(current,aim,48);
  if(aimSample&&performance.now()-aimSample.time<120){body.vx=flick;body.omega=flick/body.r;}
  flick=0;aimSample=null;
  highest=Math.max(highest,current);current=next;next=randomTier();cooldown=38;renderNext();updateArsenal();soundEffect();
}
function secretBounds() {
  const viewport=window.visualViewport,button=$('golden-secret');
  const left=viewport?.offsetLeft??0,top=viewport?.offsetTop??0;
  const width=viewport?.width??window.innerWidth,height=viewport?.height??window.innerHeight;
  return {left,top,right:left+Math.max(0,width-button.offsetWidth),bottom:top+Math.max(0,height-button.offsetHeight)};
}
function secretCorners(bounds) {
  const {left,top,right,bottom}=bounds;
  return [{x:left,y:top},{x:right,y:top},{x:left,y:bottom},{x:right,y:bottom}];
}
function placeSecret({x,y}) {
  const button=$('golden-secret');
  button.style.left=`${x}px`;button.style.top=`${y}px`;button.style.bottom='auto';
}
function moveSecret() {
  const bounds=secretBounds(),corners=secretCorners(bounds);
  const current=$('golden-secret').getBoundingClientRect();
  if(karambitReached){
    const choices=corners.map((point,index)=>({point,index})).filter(({point})=>Math.hypot(point.x-current.x,point.y-current.y)>1);
    const choice=choices[Math.floor(Math.random()*choices.length)]??{point:corners[0],index:0};
    secretCorner=choice.index;placeSecret(choice.point);
  }else{
    secretCorner=null;
    let point={x:bounds.left+Math.random()*(bounds.right-bounds.left),y:bounds.top+Math.random()*(bounds.bottom-bounds.top)};
    // Make every teleport noticeable even if randomness picks the old position.
    if(Math.hypot(point.x-current.x,point.y-current.y)<Math.max(current.width,current.height)){
      point=corners.reduce((farther,next)=>Math.hypot(next.x-current.x,next.y-current.y)>Math.hypot(farther.x-current.x,farther.y-current.y)?next:farther);
    }
    placeSecret(point);
  }
}
function resetSecretPosition() {
  karambitReached=false;secretCorner=null;
  const bounds=secretBounds();placeSecret({x:bounds.left,y:bounds.bottom});
  clearInterval(secretMoveTimer);secretMoveTimer=setInterval(moveSecret,60000);
}
function fitSecretToViewport() {
  const bounds=secretBounds();
  if(secretCorner!==null){placeSecret(secretCorners(bounds)[secretCorner]);return;}
  const current=$('golden-secret').getBoundingClientRect();
  placeSecret({x:Math.max(bounds.left,Math.min(bounds.right,current.x)),y:Math.max(bounds.top,Math.min(bounds.bottom,current.y))});
}
window.addEventListener('resize',fitSecretToViewport);
window.visualViewport?.addEventListener('resize',fitSecretToViewport);
window.visualViewport?.addEventListener('scroll',fitSecretToViewport);
